#include <array>
#include <chrono>
#include <condition_variable>
#include <cstddef>
#include <iostream>
#include <mutex>
#include <optional>
#include <thread>

using Clock=std::chrono::steady_clock;
struct Event { int value=0; Clock::time_point attempted{}; };
class EventRing {
    std::array<Event,8> slots_{};
    std::size_t head_=0,count_=0,high_water_=0;
    bool closed_=false;
    std::mutex mutex_;
    std::condition_variable readable_,writable_;
public:
    bool push(Event event) {
        std::unique_lock<std::mutex> lock(mutex_);
        writable_.wait(lock,[this]{return closed_ || count_<slots_.size();});
        if(closed_)return false;
        slots_[(head_+count_)%slots_.size()]=event;
        ++count_;
        if(count_>high_water_)high_water_=count_;
        lock.unlock();readable_.notify_one();return true;
    }
    std::optional<Event> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        readable_.wait(lock,[this]{return closed_ || count_>0;});
        if(count_==0)return std::nullopt;
        const Event event=slots_[head_];
        head_=(head_+1)%slots_.size();--count_;
        lock.unlock();writable_.notify_one();return event;
    }
    void close() {
        {std::lock_guard<std::mutex> lock(mutex_);closed_=true;}
        readable_.notify_all();writable_.notify_all();
    }
    std::size_t high_water() {
        std::lock_guard<std::mutex> lock(mutex_);return high_water_;
    }
};
struct CloseEvents { EventRing& queue; ~CloseEvents(){queue.close();} };

int main() {
    for(int run=0;run<5;++run) {
        EventRing queue;
        std::array<long long,128> response_ns{};
        std::size_t completed=0;
        long long checksum=0;
        bool ordered=true;
        const auto start=Clock::now();
        {
            std::jthread consumer([&] {
                while(const auto event=queue.pop()) {
                    if(completed>=response_ns.size()){ordered=false;continue;}
                    if(event->value!=static_cast<int>(completed)+1)ordered=false;
                    const long long value=event->value;
                    checksum+=value*value;
                    const auto finish=Clock::now();
                    response_ns[completed]=std::chrono::duration_cast<std::chrono::nanoseconds>(finish-event->attempted).count();
                    ++completed;
                }
            });
            CloseEvents closer{queue};
            for(int value=1;value<=128;++value)
                if(!queue.push(Event{value,Clock::now()}))return 2;
            queue.close();
        }
        const auto finish=Clock::now();
        const auto elapsed_ns=std::chrono::duration_cast<std::chrono::nanoseconds>(finish-start).count();
        if(completed!=128 || checksum!=707264 || !ordered || elapsed_ns<=0)return 3;
        std::cout<<"RUN "<<run<<' '<<elapsed_ns<<' '<<completed<<' '<<checksum<<' '<<ordered<<' '<<queue.high_water()<<'\n';
        for(std::size_t i=0;i<completed;++i)
            std::cout<<"LAT "<<run<<' '<<i<<' '<<response_ns[i]<<'\n';
    }
}

def run_summary(elapsed_ns,latencies_ns,completed,checksum,ordered,high_water):
    # Own bounded report contract; example observations below are synthetic.
    if type(elapsed_ns) is not int or not 0<elapsed_ns<=10**12:
        raise ValueError("invalid measured interval")
    if type(latencies_ns) is not list or len(latencies_ns)!=128:
        raise ValueError("expected 128 event observations")
    if any(type(x) is not int or not 0<=x<=elapsed_ns for x in latencies_ns):
        raise ValueError("invalid observation range")
    if type(completed) is not int or completed!=128 or type(checksum) is not int or checksum!=707264 or ordered is not True:
        raise ValueError("work contract failed")
    if type(high_water) is not int or not 1<=high_water<=8:
        raise ValueError("capacity contract failed")
    ordered_samples=sorted(latencies_ns)
    # ceil(99*128/100)=127, one-based; index126
    return {"n":128,"p99_ns":ordered_samples[126],"max_ns":ordered_samples[-1],
            "completed":completed,"high_water":high_water}

print(run_summary(10000,[100]*127+[900],128,707264,True,8))
try:
    run_summary(10000,[100]*128,127,707264,True,8)
except ValueError as error:
    print(error)
